const $=id=>document.getElementById(id);let orders=[];
async function load(){try{const r=await fetch('/api/admin/orders');const b=await r.json();if(!r.ok)throw Error(b.error);orders=b;$('message').textContent=orders.length+' orders (latest 500).';render();}catch(e){$('message').textContent=e.message;}}
function render(){$('orders').replaceChildren();for(const o of orders.filter(o=>!$('filter').value||o.status===$('filter').value)){
 const card=document.createElement('article');for(const text of [o.name+' · '+o.phone,o.email,new Date(o.created_at).toLocaleString(),JSON.parse(o.items).map(p=>p.quantity+' × '+({egg:'Single eggs',half:'Half crate',crate:'Full crate'}[p.id])).join(', '),o.method+(o.address?' · '+o.address:''),o.notes,'Payment: '+o.payment_status]){const p=document.createElement('p');p.textContent=text;card.append(p);}
 const status=document.createElement('select');status.setAttribute('aria-label','Order status');for(const value of ['new','confirmed','ready','completed','cancelled']){const option=document.createElement('option');option.value=value;option.textContent=value;status.append(option);}status.value=o.status;
 const label=document.createElement('label');label.textContent='Total including delivery (₦)';const amount=document.createElement('input');amount.type='number';amount.min='50';amount.max='1000000';amount.step='0.01';amount.value=o.amount===null?'':o.amount/100;amount.disabled=Boolean(o.payment_reference)||o.payment_status==='paid';label.append(amount);
 const save=document.createElement('button');save.textContent='Save order';save.onclick=async()=>{save.disabled=true;try{if(amount.value&&!amount.checkValidity())throw Error('Enter a valid total.');const r=await fetch('/api/admin/orders',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:o.id,status:status.value,amount:amount.value?Math.round(Number(amount.value)*100):null})});const b=await r.json();if(!r.ok)throw Error(b.error);await load();}catch(e){$('message').textContent=e.message;}finally{save.disabled=false;}};
 const link=document.createElement('a');link.textContent='Open private order link';link.href='/order.html#'+o.id+':'+o.token;link.target='_blank';link.rel='noopener';card.append(status,label,save,document.createElement('br'),link);$('orders').append(card);
}}
$('filter').onchange=render;$('refresh').onclick=load;load();
